export type Language =
  | 'es'
  | 'en'
  | 'zh'
  | 'hi'
  | 'fr'
  | 'ar'
  | 'bn'
  | 'pt'
  | 'id'
  | 'ur'
  | 'ru'
  | 'de'
  | 'ja';

export interface LanguageOption {
  code: Language;
  name: string;
  nativeName: string;
}

