/** Paso de la guía paso a paso de construcción del Dashboard en Power BI. */
export interface PowerBiGuideStep {
  title: string;
  intro: string;
  /** Ruta de la interfaz de Power BI (identificador técnico, no se traduce). */
  route?: string;
  items: string[];
  note?: string;
}

